using System.Security.Cryptography;
using System.Text;
using MySqlConnector;
namespace ClinicaEsteticaWeb.Services;
public class WebSessionService { private readonly Db _db; private readonly Config _cfg; public WebSessionService(Db db,IConfiguration c){_db=db;_cfg=new Config(c);} public async Task<(bool ok,string msg)> Login(HttpContext ctx,string login,string senha){using var x=_db.Open();using var c=new MySqlCommand("SELECT id,senha_hash,perfil,status,tentativas_falhas,bloqueado_ate FROM usuario WHERE login=@l LIMIT 1",x);c.Parameters.AddWithValue("@l",login?.Trim());using var r=c.ExecuteReader();if(!r.Read())return(false,"Usuário ou senha inválidos.");var id=r.GetInt32("id");var hash=r.GetString("senha_hash");var perfil=r.GetString("perfil");var status=r.GetString("status");var falhas=r.GetInt32("tentativas_falhas");DateTime? bloqueado=r.IsDBNull(r.GetOrdinal("bloqueado_ate"))?null:r.GetDateTime("bloqueado_ate");if(status!="ativo")return(false,"Usuário inativo.");if(bloqueado.HasValue&&bloqueado.Value>DateTime.Now)return(false,"Usuário temporariamente bloqueado.");bool ok=BCrypt.Net.BCrypt.Verify(senha??"",hash);r.Close();if(!ok){var nf=falhas+1;DateTime? nb=nf>=3?DateTime.Now.AddMinutes(5):null;using var u=new MySqlCommand("UPDATE usuario SET tentativas_falhas=@f,bloqueado_ate=@b WHERE id=@id",x);u.Parameters.AddWithValue("@f",nf);u.Parameters.AddWithValue("@b",(object)nb??DBNull.Value);u.Parameters.AddWithValue("@id",id);u.ExecuteNonQuery();return(false,"Usuário ou senha inválidos.");}using(var u=new MySqlCommand("UPDATE usuario SET tentativas_falhas=0,bloqueado_ate=NULL WHERE id=@id",x)){u.Parameters.AddWithValue("@id",id);u.ExecuteNonQuery();}var token=Convert.ToBase64String(RandomNumberGenerator.GetBytes(32));var th=Hash(token);using(var s=new MySqlCommand("UPDATE sessao SET status='encerrada' WHERE usuario_id=@u AND status='ativa'; INSERT INTO sessao(usuario_id,token_hash,criado_em,ultima_atividade,status) VALUES(@u,@t,NOW(),NOW(),'ativa')",x)){s.Parameters.AddWithValue("@u",id);s.Parameters.AddWithValue("@t",th);s.ExecuteNonQuery();}ctx.Response.Cookies.Append("Essencia.Session",token,new CookieOptions{HttpOnly=true,Secure=true,SameSite=SameSiteMode.Strict,IsEssential=true});ctx.Session.SetInt32("UserId",id);ctx.Session.SetString("Perfil",perfil);return(true,"");}
 public bool Validate(HttpContext ctx){var token=ctx.Request.Cookies["Essencia.Session"];if(string.IsNullOrWhiteSpace(token))return false;using var x=_db.Open();using var c=new MySqlCommand("SELECT s.usuario_id,s.ultima_atividade,s.status,u.perfil,u.nome FROM sessao s JOIN usuario u ON u.id=s.usuario_id WHERE s.token_hash=@t ORDER BY s.id DESC LIMIT 1",x);c.Parameters.AddWithValue("@t",Hash(token));using var r=c.ExecuteReader();if(!r.Read()||r.GetString("status")!="ativa")return false;var last=r.GetDateTime("ultima_atividade");var uid=r.GetInt32("usuario_id");var perfil=r.GetString("perfil");var nome=r.GetString("nome");if((DateTime.Now-last).TotalMinutes>=_cfg.Timeout){r.Close();Expire(token);ctx.Response.Cookies.Delete("Essencia.Session");return false;}r.Close();using var u=new MySqlCommand("UPDATE sessao SET ultima_atividade=NOW() WHERE token_hash=@t AND status='ativa'",x);u.Parameters.AddWithValue("@t",Hash(token));u.ExecuteNonQuery();ctx.Items["UserId"]=uid;ctx.Items["Perfil"]=perfil;ctx.Items["Nome"]=nome;return true;}
 public void Logout(HttpContext ctx){var t=ctx.Request.Cookies["Essencia.Session"];if(!string.IsNullOrWhiteSpace(t))Expire(t);ctx.Response.Cookies.Delete("Essencia.Session");}
 private void Expire(string t){using var x=_db.Open();using var c=new MySqlCommand("UPDATE sessao SET status='encerrada' WHERE token_hash=@t AND status='ativa'",x);c.Parameters.AddWithValue("@t",Hash(t));c.ExecuteNonQuery();}
 private static string Hash(string s){using var sha=SHA256.Create();return Convert.ToHexString(sha.ComputeHash(Encoding.UTF8.GetBytes(s))).ToLowerInvariant();}
}
